// State rule + resource data for all 51 jurisdictions (50 states + DC).
//
// Loaded from assets/data/state_rules.json, generated by tool/build_state_rules.py
// from state-driving-logs/state_logs.csv (official sources, checked 2026-10-22).
//
// Shapes mirror licenselogger-backend/docs/STATE_RULES_SCHEMA.md (contract v2):
// one StateRuleSet per public.state_rule_sets row, same field names
// (snake_case in JSON, camelCase here). The generator diffs every column
// against the backend's data migration, so the bundled asset and the server agree.
//
// `null` means "no such rule" or "not known", never zero. `fieldStatus`
// says which. Nothing in this file holds rule values.
import 'dart:convert';

import 'package:flutter/services.dart';

/// `status`: verified · partially_verified · unconfirmed
enum RuleStatus { verified, partiallyVerified, unconfirmed }

/// `requirement_kind`: log · log_any_format · certification · none · unconfirmed
enum RequirementKind { log, logAnyFormat, certification, none, unconfirmed }

/// `form_type`: full_log · certification · none · unconfirmed
enum FormType { fullLog, certification, none, unconfirmed }

/// `notarization`: required · if_signer_absent · not_stated
enum Notarization { required, ifSignerAbsent, notStated }

/// `digital_log`: accepted · listed_apps · not_stated
enum DigitalLog { accepted, listedApps, notStated }

/// `stages[].counting`: cumulative · since_previous_milestone
enum StageCounting { cumulative, sincePreviousMilestone }

T _enum<T extends Enum>(List<T> values, String? raw, T fallback) {
  if (raw == null) return fallback;
  final camel = raw.replaceAllMapped(RegExp(r'_([a-z])'), (m) => m[1]!.toUpperCase());
  for (final v in values) {
    if (v.name == camel) return v;
  }
  return fallback;
}

DateTime? _date(Object? s) => s == null || s == '' ? null : DateTime.parse(s as String);
int? _int(Object? v) => v == null ? null : (v as num).round();

/// One entry of `stages` (IA, MI).
class RuleStage {
  const RuleStage({
    required this.key,
    required this.label,
    this.totalMinutes,
    this.nightMinutes,
    this.weatherMinutes,
    required this.counting,
    this.milestone,
  });
  final String key;
  final String label;
  final int? totalMinutes;
  final int? nightMinutes;
  final int? weatherMinutes;
  final StageCounting counting;
  final String? milestone; // key of the stage that must be reached first

  factory RuleStage.fromJson(Map<String, dynamic> j) => RuleStage(
    key: j['key'] as String,
    label: j['label'] as String,
    totalMinutes: _int(j['total_minutes']),
    nightMinutes: _int(j['night_minutes']),
    weatherMinutes: _int(j['weather_minutes']),
    counting: _enum(StageCounting.values, j['counting'] as String?, StageCounting.cumulative),
    milestone: j['milestone'] as String?,
  );
}

/// One entry of `alternatives` (AL, AZ, MA, MD, MN, OR). A null target means "same as the base rule".
class RuleAlternative {
  const RuleAlternative({
    required this.key,
    required this.label,
    this.totalMinutes,
    this.nightMinutes,
    this.weatherMinutes,
    required this.replacesHours,
  });
  final String key;
  final String label;
  final int? totalMinutes;
  final int? nightMinutes;
  final int? weatherMinutes;
  final bool replacesHours;

  factory RuleAlternative.fromJson(Map<String, dynamic> j) => RuleAlternative(
    key: j['key'] as String,
    label: j['label'] as String,
    totalMinutes: _int(j['total_minutes']),
    nightMinutes: _int(j['night_minutes']),
    weatherMinutes: _int(j['weather_minutes']),
    replacesHours: j['replaces_hours'] as bool? ?? false,
  );
}

/// A downloadable official form (built from the rule set's form_* columns).
class StateForm {
  const StateForm({
    required this.formName,
    required this.formNumber,
    required this.formType,
    required this.formTypeDetail,
    this.pdfUrl,
    this.pdfStatus,
    this.isAlternate = false,
  });
  final String formName;
  final String formNumber;
  final FormType formType;
  final String formTypeDetail;
  final String? pdfUrl;
  final String? pdfStatus; // verbatim link check, e.g. "verified (HTTP 200, %PDF)"
  final bool isAlternate;

  bool get linkVerified => pdfStatus?.startsWith('verified') ?? false;
  bool get linkUnverified => pdfStatus != null && !linkVerified;
}

/// One entry of `links` (same shape as the state_resources RPC).
class StateLink {
  const StateLink({required this.kind, required this.label, required this.url, this.status, this.lastChecked});
  final String kind; // form_pdf · alt_form_pdf · handbook · parent_guide · gdl_page · source_page
  final String label;
  final String url;
  final String? status; // verbatim verification text
  final DateTime? lastChecked;

  bool get verified => status?.startsWith('verified') ?? false;
  String get host => Uri.tryParse(url)?.host.replaceFirst('www.', '') ?? url;
}

/// One version of a state's rule: a public.state_rule_sets row.
class StateRuleSet {
  StateRuleSet({
    required this.stateCode,
    required this.version,
    required this.jurisdictionName,
    required this.effectiveFrom,
    this.effectiveTo,
    required this.label,
    required this.status,
    required this.verified,
    this.verifiedOn,
    this.lastChecked,
    required this.requirementKind,
    this.totalMinutes,
    this.nightMinutes,
    required this.nightRule,
    this.nightDefinition,
    this.weatherMinutes,
    this.weatherCountsNight = false,
    this.dailyCapMinutes,
    this.weeklyCapMinutes,
    this.logUnit = 'hours',
    this.lessonsCount = false,
    this.instructorMultiplier = 1,
    this.instructorMaxMinutes,
    this.stages = const [],
    this.alternatives = const [],
    this.supervisorMinAge,
    this.supervisorMinYearsLicensed,
    this.supervisorParentExempt = false,
    this.supervisorRule = '',
    this.notarization = Notarization.notStated,
    this.notarizationNote = '',
    this.digitalLog = DigitalLog.notStated,
    this.digitalLogApps = const [],
    this.digitalLogNote = '',
    this.formType = FormType.unconfirmed,
    this.formTypeDetail = '',
    this.formName = '',
    this.formNumber = '',
    this.formPdfUrl = '',
    this.formPdfStatus = '',
    this.altFormName = '',
    this.altFormPdfUrl = '',
    this.formCode = '',
    this.formUrl = '',
    this.handbookUrl = '',
    this.parentGuideUrl = '',
    this.gdlPageUrl = '',
    this.sourceUrl = '',
    this.linkStatus = const {},
    this.otherRules = '',
    this.notes = '',
    this.fieldStatus = const {},
    this.pendingChangeOn,
    this.pendingChangeNote = '',
    this.appHints = const {},
    this.noRuleOnFile = false,
  });

  final String stateCode;
  final int version;
  final String jurisdictionName;
  final DateTime effectiveFrom; // 2000-01-01 = all permits on record
  final DateTime? effectiveTo; // exclusive; null = open-ended
  final String label;
  final RuleStatus status;
  final bool verified; // legacy
  final DateTime? verifiedOn; // legacy
  final DateTime? lastChecked;
  final RequirementKind requirementKind;
  // Hours (all minutes)
  final int? totalMinutes;
  final int? nightMinutes;
  final String nightRule;
  final String? nightDefinition;
  final int? weatherMinutes;
  final bool weatherCountsNight; // AK: "challenging conditions" = night OR bad weather
  final int? dailyCapMinutes;
  final int? weeklyCapMinutes;
  final String logUnit; // hours | minutes (display only)
  // Instructor time
  final bool lessonsCount;
  final num instructorMultiplier;
  final int? instructorMaxMinutes; // raw instructor minutes that may count
  // Stages and alternatives
  final List<RuleStage> stages;
  final List<RuleAlternative> alternatives;
  // Supervisor
  final int? supervisorMinAge;
  final num? supervisorMinYearsLicensed;
  final bool supervisorParentExempt;
  final String supervisorRule;
  // Paperwork
  final Notarization notarization;
  final String notarizationNote;
  final DigitalLog digitalLog;
  final List<String> digitalLogApps;
  final String digitalLogNote;
  final FormType formType;
  final String formTypeDetail;
  final String formName;
  final String formNumber;
  final String formPdfUrl;
  final String formPdfStatus;
  final String altFormName;
  final String altFormPdfUrl;
  final String formCode; // legacy copy of form_number
  final String formUrl; // legacy copy of form_pdf_url
  // Links
  final String handbookUrl;
  final String parentGuideUrl;
  final String gdlPageUrl;
  final String sourceUrl;
  final Map<String, String> linkStatus;
  // Notes
  final String otherRules;
  final String notes;
  final Map<String, String> fieldStatus; // field -> caveat
  final DateTime? pendingChangeOn;
  final String pendingChangeNote;

  /// App-only extras (not backend columns): permit_hold, driver_ed (quoted CSV text).
  final Map<String, Object?> appHints;

  /// Synthetic "No rule on file" result when no version covers the permit date.
  final bool noRuleOnFile;

  bool get isUnconfirmed => status == RuleStatus.unconfirmed || requirementKind == RequirementKind.unconfirmed;
  bool get noMinimum => requirementKind == RequirementKind.none;
  bool get certificationOnly => requirementKind == RequirementKind.certification;
  bool get hasTarget => !isUnconfirmed && !noMinimum && totalMinutes != null;
  String get nightLabel => 'Night';
  String get weatherLabel => weatherCountsNight ? 'Challenging conditions' : 'Bad weather';
  String? get permitHold => appHints['permit_hold'] as String?;
  String? get driverEd => appHints['driver_ed'] as String?;

  /// The per-field caveat from `field_status` (e.g. "not specified", "unconfirmed: ...").
  String? caveat(String field) => fieldStatus[field];
  bool isFieldUnconfirmed(String field) => isUnconfirmed || (caveat(field)?.startsWith('unconfirmed') ?? false);

  bool appliesTo(DateTime d) => !d.isBefore(effectiveFrom) && (effectiveTo == null || d.isBefore(effectiveTo!));

  List<StateForm> get forms => [
    if (formName.isNotEmpty)
      StateForm(
        formName: formName,
        formNumber: formNumber,
        formType: formType,
        formTypeDetail: formTypeDetail,
        pdfUrl: formPdfUrl.isEmpty ? null : formPdfUrl,
        pdfStatus: formPdfStatus.isEmpty ? null : formPdfStatus,
      ),
    if (altFormName.isNotEmpty)
      StateForm(
        formName: altFormName,
        formNumber: '',
        formType: formType,
        formTypeDetail: 'Other official form',
        pdfUrl: altFormPdfUrl.isEmpty ? null : altFormPdfUrl,
        pdfStatus: linkStatus['alt_form_pdf'],
        isAlternate: true,
      ),
  ];

  factory StateRuleSet.noRule(String code, String name, DateTime permit) => StateRuleSet(
    stateCode: code,
    version: 0,
    jurisdictionName: name,
    effectiveFrom: permit,
    label: 'No rule on file',
    status: RuleStatus.unconfirmed,
    verified: false,
    requirementKind: RequirementKind.unconfirmed,
    nightRule: 'unspecified',
    noRuleOnFile: true,
  );

  factory StateRuleSet.fromJson(Map<String, dynamic> j) {
    Map<String, String> strMap(Object? m) => {
      for (final e in (m as Map<String, dynamic>? ?? const {}).entries) e.key: '${e.value}',
    };
    return StateRuleSet(
      stateCode: j['state_code'] as String,
      version: j['version'] as int,
      jurisdictionName: j['jurisdiction_name'] as String,
      effectiveFrom: DateTime.parse(j['effective_from'] as String),
      effectiveTo: _date(j['effective_to']),
      label: j['label'] as String,
      status: _enum(RuleStatus.values, j['status'] as String?, RuleStatus.unconfirmed),
      verified: j['verified'] as bool? ?? false,
      verifiedOn: _date(j['verified_on']),
      lastChecked: _date(j['last_checked']),
      requirementKind: _enum(RequirementKind.values, j['requirement_kind'] as String?, RequirementKind.unconfirmed),
      totalMinutes: _int(j['total_minutes']),
      nightMinutes: _int(j['night_minutes']),
      nightRule: j['night_rule'] as String? ?? 'unspecified',
      nightDefinition: j['night_definition'] as String?,
      weatherMinutes: _int(j['weather_minutes']),
      weatherCountsNight: j['weather_counts_night'] as bool? ?? false,
      dailyCapMinutes: _int(j['daily_cap_minutes']),
      weeklyCapMinutes: _int(j['weekly_cap_minutes']),
      logUnit: j['log_unit'] as String? ?? 'hours',
      lessonsCount: j['lessons_count'] as bool? ?? false,
      instructorMultiplier: j['instructor_multiplier'] as num? ?? 1,
      instructorMaxMinutes: _int(j['instructor_max_minutes']),
      stages: [for (final s in (j['stages'] as List? ?? const [])) RuleStage.fromJson(s as Map<String, dynamic>)],
      alternatives: [
        for (final a in (j['alternatives'] as List? ?? const [])) RuleAlternative.fromJson(a as Map<String, dynamic>),
      ],
      supervisorMinAge: _int(j['supervisor_min_age']),
      supervisorMinYearsLicensed: j['supervisor_min_years_licensed'] as num?,
      supervisorParentExempt: j['supervisor_parent_exempt'] as bool? ?? false,
      supervisorRule: j['supervisor_rule'] as String? ?? '',
      notarization: _enum(Notarization.values, j['notarization'] as String?, Notarization.notStated),
      notarizationNote: j['notarization_note'] as String? ?? '',
      digitalLog: _enum(DigitalLog.values, j['digital_log'] as String?, DigitalLog.notStated),
      digitalLogApps: [for (final a in (j['digital_log_apps'] as List? ?? const [])) '$a'],
      digitalLogNote: j['digital_log_note'] as String? ?? '',
      formType: _enum(FormType.values, j['form_type'] as String?, FormType.unconfirmed),
      formTypeDetail: j['form_type_detail'] as String? ?? '',
      formName: j['form_name'] as String? ?? '',
      formNumber: j['form_number'] as String? ?? '',
      formPdfUrl: j['form_pdf_url'] as String? ?? '',
      formPdfStatus: j['form_pdf_status'] as String? ?? '',
      altFormName: j['alt_form_name'] as String? ?? '',
      altFormPdfUrl: j['alt_form_pdf_url'] as String? ?? '',
      formCode: j['form_code'] as String? ?? '',
      formUrl: j['form_url'] as String? ?? '',
      handbookUrl: j['handbook_url'] as String? ?? '',
      parentGuideUrl: j['parent_guide_url'] as String? ?? '',
      gdlPageUrl: j['gdl_page_url'] as String? ?? '',
      sourceUrl: j['source_url'] as String? ?? '',
      linkStatus: strMap(j['link_status']),
      otherRules: j['other_rules'] as String? ?? '',
      notes: j['notes'] as String? ?? '',
      fieldStatus: strMap(j['field_status']),
      pendingChangeOn: _date(j['pending_change_on']),
      pendingChangeNote: j['pending_change_note'] as String? ?? '',
      appHints: (j['app_hints'] as Map<String, dynamic>?) ?? const {},
    );
  }
}

class Jurisdiction {
  const Jurisdiction({
    required this.stateCode,
    required this.jurisdictionName,
    this.lastChecked,
    required this.ruleSets,
    required this.links,
  });
  final String stateCode;
  final String jurisdictionName;
  final DateTime? lastChecked;
  final List<StateRuleSet> ruleSets; // oldest first
  final List<StateLink> links;

  String get stateName => jurisdictionName;
  StateRuleSet get latest => ruleSets.last;
  bool get isUnconfirmed => latest.isUnconfirmed;

  /// Handbook, parent guide, GDL page, source page (form PDFs are shown with the forms).
  List<StateLink> get resources => links.where((l) => !l.kind.contains('form')).toList();

  /// Contract rule (section 1): effective_from <= d < effective_to; newest effective_from, then
  /// highest version, wins. No match -> a "No rule on file" placeholder (e.g. SD permits before 2020-07-01).
  StateRuleSet ruleFor(DateTime? permitIssued) {
    final d = permitIssued ?? DateTime.now();
    final hits = ruleSets.where((r) => r.appliesTo(d)).toList()
      ..sort((a, b) {
        final c = b.effectiveFrom.compareTo(a.effectiveFrom);
        return c != 0 ? c : b.version.compareTo(a.version);
      });
    return hits.isEmpty ? StateRuleSet.noRule(stateCode, jurisdictionName, d) : hits.first;
  }

  factory Jurisdiction.fromJson(Map<String, dynamic> j) {
    final checked = _date(j['last_checked']);
    return Jurisdiction(
      stateCode: j['state_code'] as String,
      jurisdictionName: j['jurisdiction_name'] as String,
      lastChecked: checked,
      ruleSets: [for (final r in j['rule_sets'] as List) StateRuleSet.fromJson(r as Map<String, dynamic>)],
      links: [
        for (final l in j['links'] as List)
          StateLink(
            kind: (l as Map<String, dynamic>)['kind'] as String,
            label: l['label'] as String,
            url: l['url'] as String,
            status: l['status'] as String?,
            lastChecked: checked,
          ),
      ],
    );
  }
}

class StateRulesRepo {
  StateRulesRepo(this.jurisdictions) : _byCode = {for (final j in jurisdictions) j.stateCode: j};
  final List<Jurisdiction> jurisdictions;
  final Map<String, Jurisdiction> _byCode;

  static const asset = 'assets/data/state_rules.json';

  static Future<StateRulesRepo> load([AssetBundle? bundle]) async {
    final raw = await (bundle ?? rootBundle).loadString(asset);
    return StateRulesRepo.fromJsonString(raw);
  }

  factory StateRulesRepo.fromJsonString(String raw) {
    final j = jsonDecode(raw) as Map<String, dynamic>;
    return StateRulesRepo([
      for (final x in j['jurisdictions'] as List) Jurisdiction.fromJson(x as Map<String, dynamic>),
    ]);
  }

  Jurisdiction operator [](String code) => _byCode[code]!;

  Jurisdiction? tryGet(String code) => _byCode[code];

  Jurisdiction? byNameOrAbbr(String nameOrAbbr) {
    final key = nameOrAbbr.trim().toLowerCase();
    if (key.isEmpty) return null;
    final direct = _byCode[nameOrAbbr.trim().toUpperCase()];
    if (direct != null) return direct;
    for (final j in jurisdictions) {
      if (j.stateCode.toLowerCase() == key || j.stateName.toLowerCase() == key) {
        return j;
      }
    }
    return null;
  }
}
